import type { Register } from 'claude-code'
import { decide, type Effort, type Seen } from './decide'

const KEY = 'byModel'
let seen: Seen = {}
let polled: string | undefined
let applied: string | undefined // `${model}:${effort}` last put on the session

async function saved($: any): Promise<Record<string, Effort>> {
  return ((await $.store.get(KEY)) ?? {}) as Record<string, Effort>
}

function restore($: any, model: string, effort: Effort) {
  if (applied === `${model}:${effort}`) return
  applied = `${model}:${effort}`
  // queued until the session is idle; makes it the session's effort, so the UI shows it
  $.command.run({ command: 'effort', args: String(effort) }).catch(() => {})
  $.ui.toast(`effort ${effort} restored for ${model}`)
}

export const register: Register = on => {
  // Switch the effort the moment the model changes, before any prompt is sent.
  on('session.start', async ($, e, next) => {
    const r = await next(e)
    // ponytail: 1s poll, the mod API has no model-changed event
    $.clock.every(1000, async () => {
      const model = await $.session.model()
      if (model === polled) return
      polled = model
      const effort = (await saved($))[model]
      if (effort !== undefined) restore($, model, effort)
    })
    return r
  })

  // Every request: record the effort per model, and restore it if the poll hasn't yet.
  on('turn.step', async function* ($, e, next) {
    // subagents run with their own effort; leave them be
    if (e.agentId !== undefined || e.effort === undefined) return yield* next(e)

    const byModel = await saved($)
    const d = decide(seen, e.model, e.effort, byModel[e.model])
    seen = d.seen
    polled = e.model

    if (d.restore) restore($, e.model, d.use!)
    applied = `${e.model}:${d.use}`
    if (byModel[e.model] !== d.use) await $.store.set(KEY, { ...byModel, [e.model]: d.use })

    return yield* next(d.restore ? { ...e, effort: d.use } : e)
  })
}

