export type Effort = 'low' | 'medium' | 'high' | 'xhigh' | 'max' | number
export type Seen = { model?: string; effort?: Effort }

// Model changed and the session's effort is still the one carried over
// (not touched since the last request) → use what this model had last time.
export function decide(seen: Seen, model: string, effort: Effort | undefined, saved: Effort | undefined) {
  const carried = seen.model === undefined || effort === seen.effort
  const restore = effort !== undefined && model !== seen.model && carried && saved !== undefined && saved !== effort
  const use = restore ? saved : effort
  // a model without effort leaves the last seen effort as it was
  return { use, restore, seen: { model, effort: use ?? seen.effort } }
}
